import{_ as a,o as s,c as l,a as e}from"./app.83c7065c.js";const C=JSON.parse('{"title":"CST与GMT的差别","description":"","frontmatter":{"title":"CST与GMT的差别","date":"2018-05-15"},"headers":[],"relativePath":"2018/cst-vs-gmt.md","lastUpdated":1786184870000}'),n={name:"2018/cst-vs-gmt.md"},o=e(`<ul><li><a href="#date-2018-05-15">date: 2018-05-15</a><ul><li><a href="#%E9%97%AE%E9%A2%98%E6%8F%8F%E8%BF%B0">问题描述</a></li><li><a href="#%E6%8E%92%E6%9F%A5%E8%BF%87%E7%A8%8B">排查过程</a></li><li><a href="#cst--gmt-%E5%86%B7%E7%9F%A5%E8%AF%86">CST &amp; GMT 冷知识</a></li><li><a href="#%E9%97%AE%E9%A2%98%E8%A7%A3%E5%86%B3">问题解决</a></li><li><a href="#%E5%8F%8D%E6%80%9D">反思</a></li></ul></li></ul><h4 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-hidden="true">#</a></h4><p>今天偶然发现了一个问题，JAVA 后台返回的时间字符串解析后居然比原始数据差了 14 个小时<br> 后台时间字符串：<code>Thu Feb 17 16:31:52 CST 2018</code><br> 前端解析时间： <code>Sun Feb 18 2018 06:31:52 GMT</code></p><h4 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-hidden="true">#</a></h4><ol><li>前端传的是时间戳，后台自己并没有处理，而且显示的时间与前端传的时间完全一致</li><li>只有后台再发送给前端之后时间显示才出现问题，妥妥前端的锅</li></ol><p>再看一眼 2 个字符串的样子，很自然想到不一致来源于 CST 和 GMT 这两种不同标准</p><h4 id="cst-gmt-冷知识" tabindex="-1">CST &amp; GMT 冷知识 <a class="header-anchor" href="#cst-gmt-冷知识" aria-hidden="true">#</a></h4><p>google 了一下，CST 可以代表以下几个时间：</p><ul><li><code>Central Standard Time (USA) UT-6:00</code></li><li><code>Central Standard Time (Australia) UT+9:30</code></li><li><code>China Standard Time UT+8:00</code></li><li><code>Cuba Standard Time UT-4:00</code></li></ul><p>换句话说，CST 可以代表 4 个不同的时区，而 GMT 只代表格林尼治标准时间</p><p>那么很显然问题的原因找到了：</p><ul><li><code>JAVA</code>认为<code>CST</code>代表的是<code>China Standard Time +8</code></li><li><code>而Javascript</code>认为<code>CST</code>代表的是<code>Central Standard Time (USA) -6</code></li></ul><p>所以前端计算时才有了<code>8-(-6)=14</code>小时的时差</p><h4 id="问题解决" tabindex="-1">问题解决 <a class="header-anchor" href="#问题解决" aria-hidden="true">#</a></h4><p>写了个简单的方法处理了时差问题</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> dateCstToGmt </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#A6ACCD;font-style:italic;">dateString</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">=&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#C792EA;">let</span><span style="color:#F07178;"> </span><span style="color:#A6ACCD;">aDate</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">=</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">new</span><span style="color:#F07178;"> </span><span style="color:#82AAFF;">Date</span><span style="color:#F07178;">(</span><span style="color:#A6ACCD;">dateString</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#C792EA;">const</span><span style="color:#F07178;"> </span><span style="color:#A6ACCD;">hour</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">=</span><span style="color:#F07178;"> </span><span style="color:#A6ACCD;">aDate</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">getHours</span><span style="color:#F07178;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#A6ACCD;">aDate</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">setHours</span><span style="color:#F07178;">(</span><span style="color:#A6ACCD;">hour</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">-</span><span style="color:#F07178;"> </span><span style="color:#F78C6C;">14</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;font-style:italic;">return</span><span style="color:#F07178;"> </span><span style="color:#A6ACCD;">aDate</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">};</span></span>
<span class="line"></span></code></pre></div><h4 id="反思" tabindex="-1">反思 <a class="header-anchor" href="#反思" aria-hidden="true">#</a></h4><ul><li>最优方案：最好统一用时间戳，这样前后台解析都不会有错</li><li>次优方案：如果一定要用时间字符串，那么用没有歧义的 GMT 时间比 CST 时间来得可靠</li></ul>`,18),t=[o];function p(c,r,i,d,F,y){return s(),l("div",null,t)}const h=a(n,[["render",p]]);export{C as __pageData,h as default};
